    TEST_ASSERT_EQUAL_STRING("167%, 94%", g_p.initial);
    TEST_ASSERT_EQUAL(1, rule("--p20", "inherits: false; syntax: '<angle>+ | _under'; initial-value: _under"));
    TEST_ASSERT_EQUAL(WF_CSSPROP_COMPLEX, g_p.syntax);
    TEST_ASSERT_EQUAL(2, g_p.nalt);
    TEST_ASSERT_EQUAL(0, g_p.inherits);
    TEST_ASSERT_EQUAL_STRING("_under", g_p.initial);
    TEST_ASSERT_EQUAL(0, rule("--p95", "initial-value: a1; syntax: 'red | red#'; inherits: false"));
    TEST_ASSERT_EQUAL(0, g_p.name[0]);
    TEST_ASSERT_EQUAL(1, rule("--p44", "initial-value: 30.1s	1.8ms; syntax: '<time>+'; inherits: false"));
    TEST_ASSERT_EQUAL(WF_CSSPROP_COMPLEX, g_p.syntax);
    TEST_ASSERT_EQUAL(1, g_p.nalt);
    TEST_ASSERT_EQUAL(0, g_p.inherits);
    TEST_ASSERT_EQUAL_STRING("30.1s	1.8ms", g_p.initial);
    TEST_ASSERT_EQUAL(1, rule("--p21", "initial-value: min(105deg, 92turn + calc(44.4deg)); inherits: true; syntax: '<percentage> | <angle>+ | <color> | <length>'"));
